CREATE EXTENSION IF NOT EXISTS pgcrypto;
ALTER TABLE user_access ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ,ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();ALTER TABLE user_access ALTER COLUMN lifetime SET DEFAULT FALSE;UPDATE user_access SET lifetime=FALSE,activated_at=COALESCE(activated_at,NOW()),expires_at=COALESCE(expires_at,NOW()+INTERVAL '365 days'),updated_at=NOW() WHERE status='active';UPDATE user_access SET lifetime=FALSE,updated_at=NOW() WHERE status<>'active' AND lifetime=TRUE;CREATE INDEX IF NOT EXISTS access_expiration_idx ON user_access(status,expires_at);
CREATE TABLE IF NOT EXISTS user_profiles(user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,full_name VARCHAR(180),cpf VARCHAR(14),birth_date DATE,phone VARCHAR(24),whatsapp VARCHAR(24),address_line VARCHAR(240),address_number VARCHAR(30),address_extra VARCHAR(120),district VARCHAR(120),city VARCHAR(120),state CHAR(2),postal_code VARCHAR(10),instagram VARCHAR(160),linkedin VARCHAR(240),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE UNIQUE INDEX IF NOT EXISTS user_profiles_cpf_uidx ON user_profiles(cpf) WHERE cpf IS NOT NULL;
CREATE TABLE IF NOT EXISTS payment_orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider VARCHAR(40) NOT NULL DEFAULT 'mercado_pago',provider_preference_id VARCHAR(180),provider_payment_id VARCHAR(180),status VARCHAR(30) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','cancelled','refunded','charged_back','failed','review')),raw_status VARCHAR(240),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),currency CHAR(3) NOT NULL DEFAULT 'BRL',description VARCHAR(180) NOT NULL,approved_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE UNIQUE INDEX IF NOT EXISTS payment_orders_preference_uidx ON payment_orders(provider,provider_preference_id) WHERE provider_preference_id IS NOT NULL;CREATE UNIQUE INDEX IF NOT EXISTS payment_orders_payment_uidx ON payment_orders(provider,provider_payment_id) WHERE provider_payment_id IS NOT NULL;CREATE INDEX IF NOT EXISTS payment_orders_user_date_idx ON payment_orders(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS exam_sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,subject VARCHAR(120) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'in_progress' CHECK(status IN('in_progress','completed','expired','abandoned')),question_ids JSONB NOT NULL DEFAULT '[]'::jsonb,total_questions INTEGER NOT NULL DEFAULT 0,current_index INTEGER NOT NULL DEFAULT 0,answered_count INTEGER NOT NULL DEFAULT 0,correct_count INTEGER NOT NULL DEFAULT 0,started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),expires_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,finish_reason VARCHAR(24),attempt_id BIGINT UNIQUE REFERENCES exam_attempts(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE UNIQUE INDEX IF NOT EXISTS exam_sessions_one_active_uidx ON exam_sessions(user_id,subject) WHERE status='in_progress';CREATE INDEX IF NOT EXISTS exam_sessions_expiration_idx ON exam_sessions(status,expires_at);CREATE INDEX IF NOT EXISTS exam_sessions_user_date_idx ON exam_sessions(user_id,subject,started_at DESC);
CREATE TABLE IF NOT EXISTS exam_session_answers(id BIGSERIAL PRIMARY KEY,session_id UUID NOT NULL REFERENCES exam_sessions(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,question_id VARCHAR(120) NOT NULL,position INTEGER NOT NULL,selected_answer VARCHAR(1) NOT NULL CHECK(selected_answer IN('A','B','C','D','E')),is_correct BOOLEAN NOT NULL,response_time_ms INTEGER,answered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(session_id,question_id),UNIQUE(session_id,position));CREATE INDEX IF NOT EXISTS exam_session_answers_user_idx ON exam_session_answers(user_id,answered_at DESC);
ALTER TABLE question_answers ADD COLUMN IF NOT EXISTS session_id UUID;DO $$BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='question_answers_session_fk') THEN ALTER TABLE question_answers ADD CONSTRAINT question_answers_session_fk FOREIGN KEY(session_id) REFERENCES exam_sessions(id) ON DELETE SET NULL;END IF;END$$;CREATE UNIQUE INDEX IF NOT EXISTS question_answers_session_question_uidx ON question_answers(session_id,question_id) WHERE session_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS question_notebooks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(180) NOT NULL,subjects JSONB NOT NULL DEFAULT '[]'::jsonb,question_refs JSONB NOT NULL DEFAULT '[]'::jsonb,total_questions INTEGER NOT NULL CHECK(total_questions BETWEEN 1 AND 100),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS question_notebooks_user_idx ON question_notebooks(user_id,created_at DESC);CREATE TABLE IF NOT EXISTS question_notebook_answers(id BIGSERIAL PRIMARY KEY,notebook_id UUID NOT NULL REFERENCES question_notebooks(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,subject VARCHAR(120) NOT NULL,question_id VARCHAR(120) NOT NULL,selected_answer VARCHAR(1) NOT NULL CHECK(selected_answer IN('A','B','C','D','E')),is_correct BOOLEAN NOT NULL,response_time_ms INTEGER,answered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(notebook_id,subject,question_id));
